  addModule(moduleName, model) {
    this.powerSources.push({ name: moduleName, model });
    this.loadBalancers.push({ name: moduleName, capacity: 100 });
  }

  powerNeeded(nodeId) {
    if (this.powerSources.length === 0) return 0;
    let sum = this.powerSources.reduce((accumulator, current) => accumulator + current.capacity, 0);
